ProjectALife.DialogueShards["scenes_plan_2"] = {
{"fw_ld5_radio_b007","plan",2,"reg=civilian,family,worker,rescue|x1=f|day=0,4|mood=fear",{1,"Try a payphone, the one outside the Dairy Bar, I got a pocket full of--",2,"Phones are down, Cathy, I called my mother a hundred times",1,"A payphone's different, it's got its own line",2,"It ain't different, but go ahead, I'll watch the street"}},
{"fw_ld5_radio_b008","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=calm|world=vehicle",{1,"The car's still got a radio, we can sit in it and listen, it runs off the battery",2,"Won't that kill the battery?",1,"An hour a day, tops, turn the damn engine over once in a while",2,"I'd sit in that car an hour for anything, even a preacher"}},
{"fw_ld5_radio_b009","plan",2,"reg=civilian,family,worker,rescue|day=0,6|mood=fear",{1,"There's that tone again, then the same message, stay in your homes, remain calm",2,"Same thing since Friday night",1,"Somebody's gotta change it, somebody has to come on, say something NEW",2,"They change it, we'll hear it, keep the dial on, I'll take the first shift"}},
{"fw_ld5_radio_b010","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"High school's got a radio room, the kids ran a station, five watts, whole school heard it",2,"Five watts goes about a mile",1,"A mile's all we need, it's town we wanna talk to",2,"I get to be the DJ, I been waiting my whole life for this"}},
{"fw_ld5_radio_b011","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=grim",{1,"There's an AM station in Brandenburg, a little one, they play gospel, farm prices",2,"Brandenburg's a day's walk",1,"If somebody's still on the air it's them, nobody else would have the sense",2,"And if nobody's there? We just burned two days",1,"Then we know, I'd rather know"}},
{"fw_ld5_radio_b012","plan",2,"reg=family|mood=funny",{1,"Tatum's got the only satellite dish in the county, big as a swimming pool",2,"Dish ain't gonna get nothing if NOBODY's broadcasting",1,"You, you don't know that, maybe somebody up in Nashville is",2,"Maybe... fine, I'll bring a chair, we'll watch static together"}},
{"fw_ld5_radio_b013","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Would children's walkie-talkies be any use if we found a pair?",2,"What the hell do we need those for?",1,"Might let us talk without shouting. We'd have to try the range before splitting up",2,"...Okay",2,"that's actually smart, I take it back"}},
{"fw_ld5_radio_b014","plan",2,"reg=worker|day=5,40|mood=grim",{1,"Tower out on the ridge, three hundred feet, used to blink red at night",2,"It ain't blinking now",1,"Don't matter, the antenna's still up, hook a battery radio to it, we hear everything",2,"We climb three hundred feet to hear static, I'm not that curious",1,"I am, you wait at the bottom"}},
{"fw_ld5_radio_b015","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"Guy at the damn gas station said the Army's got a station at Knox, reads instructions every hour",2,"Which station?!",1,"He didn't know, you just turn the dial slow, hope for the best",2,"Slow, fine, but we're not doing it in the open, do it in the back room"}},
{"fw_ld5_radio_b016","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=angry",{1,"This radio's got four bars of battery and one station that's a loop, I'm gonna throw it--",2,"Don't throw it, that's our only radio",1,"Then somebody find me another one! Somebody go find a radio!",2,"I'll check the houses on Elm tomorrow, every house has a radio, calm down!"}},
{"fw_ld5_radio_b017","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"I turned the TV on again, same screen, the colored bars, I'm gonna try it one more--",2,"Don't-- don't, you'll waste the generator",1,"I just wanna see someone's face, any face, Dan Rather, anybody",2,"...Okay, ten minutes, then it goes off, tomorrow we go look for real news"}},
{"fw_ld5_radio_b018","plan",2,"reg=worker|day=5,40|mood=calm",{1,"Utility company's got a radio room, linemen talk to each other all day, there's a base station",2,"Power's out everywhere",1,"Base station's got a battery backup, I worked two summers there, the batteries last a week, maybe two",2,"Maybe two weeks, so go now, tomorrow it's dead"}},
{"fw_ld5_radio_b019","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"My uncle had a shortwave, the big Zenith, he listened to Cuba, Russia, the BBC",2,"BBC would tell us what's happening",1,"BBC would say it in a nice accent, I need a nice accent right now, I need someone calm",2,"We find the uncle's house and the radio, you get your accent"}},
{"fw_ld5_radio_b020","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"It's QUIET on the dial, that's what scares me, there's usually some preacher",2,"They all went off the air Saturday",1,"Somebody's still got a transmitter, it's just a matter of finding where",2,"That's the plan, every radio we can get our hands on, we hunt one down"}},
{"fw_ld5_radio_b021","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"What-- what if we get on the air ourselves? We say hello, we say where we are",2,"And every dead thing within ten miles tunes in",1,"Fine, we say hello quietly",2,"You can't say hello quietly on a radio, dummy"}},
{"fw_ld5_radio_b022","plan",2,"reg=family|mood=sad",{1,"Radio at the funeral home's always on, the director had it tuned to the oldies",2,"That's not gonna tell us anything",1,"It's gonna tell us if somebody's playing oldies, and if somebody's playing oldies somebody's alive",2,"...I'll go, I just don't wanna go in that building"}},
{"fw_ld5_radio_b023","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Fire station's got a scanner, I used to hear it crackling from the bleachers at the game",2,"A scanner hears police and fire, and ambulance",1,"And whoever's left, that's all I'm asking, one voice",2,"We go, and we sit there as long as it takes, I got nothing else"}},
{"fw_ld5_radio_b024","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"If we find a radio station I'm requesting a song",2,"You're requesting a song",1,"One song, My Old Kentucky Home, I don't care which one, they owe us",2,"Nobody owes you a song, Rita, but yes, I'd request one too"}},
{"fw_ld5_radio_b025","plan",2,"reg=civilian,family,worker,rescue|x1=m|mood=grim",{1,"I put batteries in the walkman, you know what's on it?",2,"What?",1,"Nothing, it's an old mixtape, but I put it on, I listened to a man sing about a truck, I cried",2,"Then we're finding a real radio, Doug, I'm not having you cry over a truck"}},
{"fw_ld5_radio_b026","plan",2,"reg=civilian,family,worker,rescue|day=0,8|mood=fear",{1,"Mom said to listen on the hour, that's when they'd have the news",2,"There's no news, there's a tone",1,"Mom said on the hour, so on the hour it is",2,"...Okay, we listen on the hour, I'll set the watch, NOBODY talk during it"}},
{"fw_ld5_louisville_b027","plan",3,"reg=civilian,family,worker,rescue|day=1,14|mood=calm",{1,"Louisville's thirty miles, we could do thirty miles",2,"On what? Dixie's wall to wall cars, I saw it from the overpass",3,"The railroad, then, tracks go straight up there, nobody drives tracks",1,"Tracks! Yeah! TRACKS",2,"...Jesus, fine, but I'm bringing water, a lot of water"}},
{"fw_ld5_louisville_b028","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=angry",{1,"My sister's in Shively, I gotta get to her",2,"Louisville's the worst place there is right now, everybody says so",1,"I don't CARE what everybody says!",2,"Hey, hey, nobody said don't, we just do it smart, you ain't walking in there with nothing",1,"Then WHAT? Tell me what!",2,"We go together, on the tracks, you carry something that shoots"}},
{"fw_ld5_louisville_b029","plan",2,"reg=civilian,family,worker,rescue|day=0,6|hour=5,12|mood=fear",{1,"You see that glow over the city last night? The whole sky was orange",2,"That's, that's Louisville, that's thirty miles off",1,"Then it's all burning, there's nothing up there to go to",2,"So we don't go north, we STAY south, we find somewhere that ain't on fire"}},
{"fw_ld5_louisville_b030","plan",2,"reg=civilian,family,worker,rescue|day=1,8|mood=fear",{1,"Radio said the Army's flying people out of Standiford Field",2,"When did it say that?!",1,"Friday night, right before it went to the tone",2,"Friday's three days ago",1,"So we go NOW, the longer we wait the less there's gonna be at the end of it"}},
{"fw_ld5_louisville_b031","plan",2,"reg=family|day=2,14|mood=sad",{1,"Mama's got dialysis Tuesdays and Fridays, she's missed two now",2,"There's nowhere to do it here",1,"University Hospital in Louisville has a whole floor of it, I took her there once",2,"Thirty miles with a woman on a machine schedule, and nobody's running a hospital",1,"I know that! I know! Just let me say it out loud, it's the only place I can think of"}},
{"fw_ld5_louisville_b032","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Indiana's across the bridge, nobody's said a word about Indiana",2,"Nobody's said a word about anything",1,"Exactly, might be fine, might be farm country, quiet",2,"Might have soldiers on the bridge too, I ain't going till somebody looks first"}},
{"fw_ld5_louisville_b033","plan",2,"reg=worker|day=3,30|mood=calm",{1,"The hub by the airport had a thousand pallets of everything, my cousin worked nights there",2,"A hub'd have its own generator",1,"And a cafeteria, a first aid room, boxes nobody ever picked up",2,"So we're not going to Louisville, we're going to the hub, call it what it is"}},
{"fw_ld5_louisville_b034","plan",2,"reg=civilian,family,worker,rescue|hour=5,12|mood=calm",{1,"We make Valley Station today, that's twenty-two miles",2,"Twenty-two?! On Dixie the whole way?",1,"We take the tracks, we sleep in the first church we see after",2,"And if the church is full of them?",1,"Then we sleep in a ditch, God, I don't know, quit asking me"}},
{"fw_ld5_louisville_b035","plan",2,"reg=worker|mood=calm",{1,"My cousin's got a johnboat at the ramp in West Point, nine-horse Evinrude",2,"Up the Ohio to Louisville?",1,"Two hours, maybe, go ashore at the park by the bridges",2,"Floating up the river with the dead on the banks, I don't know about that"}},
{"fw_ld5_louisville_b036","plan",2,"reg=civilian,family,worker,rescue|day=2,14|mood=grim",{1,"A guy came through from Louisville yesterday, walked the whole way",2,"What-- what the hell'd he say?",1,"Nothing, he sat in the church with his shoes off six hours, stared at the wall",2,"...Then we're not going to Louisville"}},
{"fw_ld5_louisville_b037","plan",2,"reg=civilian,family,worker,rescue|day=5,40|mood=funny",{1,"Churchill Downs has stables for a hundred horses and a grandstand with a roof",2,"You wanna move into a racetrack",1,"Fences, a tunnel under the track, and the betting window's closed, nobody's losing money",2,"...I'd bet on us making it that far, honestly"}},
{"fw_ld5_knox_b038","plan",2,"reg=civilian,family,worker,rescue|day=2,14|mood=fear",{1,"We walk up to the damn gate with our hands up and a bedsheet on a stick",2,"What if they shoot first?",1,"They're soldiers, they ain't gonna shoot a woman waving a bedsheet",2,"You say that like you didn't hear about the bridge"}},
{"fw_ld5_knox_b039","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"The truck with the loudspeaker said Fort Knox is taking people, I heard it myself",2,"Which gate?",1,"Main gate, one bag a person, no weapons",2,"No weapons, I'm not walking up there with nothing, I'll hide the shotgun in the weeds"}},
{"fw_ld5_knox_b040","plan",2,"reg=civilian,family,worker,rescue|x1=m|mood=warm",{1,"My brother's a tanker at Knox, Specialist Hatch, anybody there'll know him",2,"You haven't talked to him in a year",1,"So what, he's my brother, he'll come to the gate",2,"If he's alive, and if they let him, and if you don't get shot on the way, Cody"}},
{"fw_ld5_knox_b041","plan",2,"reg=civilian,family,worker,rescue|day=1,10|mood=grim",{1,"Ireland Army hospital's on the base, a real hospital, with generators",2,"If it's still running it's the only one",1,"My leg ain't gonna fix itself, I'm done pretending",2,"We go, we leave the guns at the fence, I'll carry your bag"}},
{"fw_ld5_knox_b042","plan",2,"reg=civilian,family,worker,rescue|x1=m|mood=funny",{1,"We get to Fort Knox, I'm asking to see the gold",2,"It's a vault, Larry, the damn door weighs twenty tons",1,"I'll knock",2,"I'll hold your coat"}},
{"fw_ld5_knox_b043","plan",2,"reg=civilian,family,worker,rescue|day=2,14|hour=18,4|mood=fear",{1,"We go at first light, hands up, no flashlights, we don't wake the guards the wrong way",2,"They, they got guards on towers?",1,"They got guards, they got dogs, they got everything, that's why we go in daylight with a sheet",2,"Sleep, I'll watch, we're up at four"}},
{"fw_ld5_knox_b044","plan",2,"reg=civilian,family,worker,rescue|mood=angry",{1,"The soldiers at the damn wire told us to turn around, they didn't even look at us",2,"They looked at you, Gary, you just didn't see it",1,"They, they said go home, I said I got no home, they said go home",2,"So we go around, there's gotta be a gate on the other side, there's always a back gate"}},
{"fw_ld5_knox_b045","plan",2,"reg=civilian,family,worker,rescue|day=5,40|mood=funny",{1,"I remember the tanks at the Patton Museum. Real ones, sitting in a field",2,"Nobody's driving a tank",1,"I used to wonder what sleeping inside one would be like",2,"I'd wonder whether I could get back out. A hatch isn't a whole plan"}},
{"fw_ld5_knox_b046","plan",2,"reg=civilian,family,worker,rescue|day=1,8|mood=fear",{1,"Remember the helicopters headed for Godman Field?",2,"Used to hear them near the Army airstrip",1,"I keep picturing somebody waving a sheet, hoping for a ride",2,"Hoping's one thing. You can't build a plan around a pilot seeing a sheet"}},
{"fw_ld5_knox_b047","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"A patrol comes down Dixie every morning, soldiers in a Humvee",2,"They don't stop",1,"They'd stop if we stood in the road and made 'em",2,"In the road... fine, but I'm standing behind you, in case they don't"}},
{"fw_ld5_evac_b048","plan",2,"reg=civilian,family,worker,rescue|x2=m|day=0,5|mood=fear",{1,"They said the school gym, buses at noon, one bag each, no pets",2,"I'm bringing the dog",1,"Dog's NOT a bag",2,"Dog's my bag, Frank, you go on, I'll come later with the dog"}},
{"fw_ld5_evac_b049","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"National Guard armory in Brandenburg, that's where they'd gather everybody",2,"How do you know?",1,"My brother-in-law was Guard, they drill there, big lot, a fence",2,"That's twelve miles, we leave first thing, boots on"}},
{"fw_ld5_evac_b050","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"There was a paper stapled to a telephone pole, EVACUATION POINT, an arrow, nothing else",2,"An arrow pointing where?",1,"North toward the river, somebody drew it in marker, I don't think it was the Army",2,"I ain't following a marker arrow, I wanna see it printed"}},
{"fw_ld5_evac_b051","plan",2,"reg=civilian,family,worker,rescue|day=3,14|mood=angry",{1,"They, they said wait for the trucks, wait for the trucks, I waited three days for the trucks",2,"Nobody's coming, I been telling you",1,"The whole time I'm sitting there being good, being quiet, like they said!",2,"We stop waiting, we pick a direction, we stick to it"}},
{"fw_ld5_evac_b052","plan",2,"reg=civilian,family,worker,rescue|day=1,8|mood=fear",{1,"Trucks were all going north toward the Second Street bridge, a line of 'em",2,"What's on the Indiana side?!",1,"Camp, says one guy, nothing, says another, bridge is blocked, says a third",2,"We go see, together, NOBODY wanders off"}},
{"fw_ld5_evac_b053","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Marina's got a few houseboats and the diesel's still in the tanks",2,"A houseboat's a floating house, nothing climbs onto a boat in the middle of the river",1,"Nothing that can't swim, which is most of 'em",2,"That's it, we move onto a houseboat, float out, wait, I like it"}},
{"fw_ld5_evac_b054","plan",2,"reg=civilian,family,worker,rescue|day=1,8|mood=fear",{1,"If a helicopter comes we gotta be in the open, a field, with something bright",2,"Bright like what?!",1,"The red tablecloth from the kitchen, we spread it on the ground, we wave it",2,"I'm taking the tablecloth, we sit in a field in the sun waiting on God"}},
{"fw_ld5_evac_b055","plan",2,"reg=civilian,family,worker,rescue|day=1,8|mood=fear",{1,"They're using the stadium in Rosewood, the Army's sorting people on the goddamn field",2,"Sorting how? Healthy here, sick there?",1,"I don't know, just sorting, it's what I heard",2,"If they sort me wrong I'm having a long talk with somebody, but fine, I'm in"}},
{"fw_ld5_panic_b056","plan",3,"reg=civilian,family,worker,rescue|day=0,3|mood=fear",{1,"We can't stay here, we CAN'T, they're in the street now",2,"Where the hell's better? Where?!",1,"The church! Pastor's got a lock and a basement!",2,"Church, church, okay, who's got the baby?",3,"Me, I got her, GO!"}},
{"fw_ld5_panic_b057","plan",2,"reg=civilian,family,worker,rescue|x1=m|day=0,3|mood=angry",{1,"TV said STAY inside, so I'm staying inside!",2,"TV's been bars and a beep for four hours, Walt",1,"Then it's still on, somebody's still in charge!",2,"Nobody's in charge! Go outside and look, I dare you"}},
{"fw_ld5_panic_b058","plan",2,"reg=family|x2=m|day=0,2|mood=fear",{1,"Last I knew, the kids were at school. I can't stop thinking about going back",2,"You, you can't! Not by yourself!",1,"Seven and nine, Ray. I know I don't know where they are now. That's what scares me",2,"Then let's work out what you know before you rush off. I'm listening"}},
{"fw_ld5_panic_b059","plan",2,"reg=family|day=0,3|mood=fear",{1,"Dad's at the plant, second shift, he doesn't even know",2,"Plant's six miles, we can't walk six miles",1,"We can't sit here either!",2,"...I know, I know, get your shoes, we try the truck first"}},
{"fw_ld5_panic_b060","plan",2,"reg=civilian,family,worker,rescue|day=0,2|hour=5,22|mood=fear",{1,"I remember a whole night of sirens. Every direction",2,"Did you know where they were going?",1,"Couldn't tell. Sounded like they never stopped",2,"I'd have wanted to get away from the noise too. Without knowing what was making it"}},
{"fw_ld5_panic_b061","plan",2,"reg=civilian,family,worker,rescue|day=0,2|mood=fear",{1,"Gas line at the Marathon goes around the block, people are fighting",2,"So no gas",1,"No gas, no nothing, the Kroger's the same, I saw a guy with a TV in a cart",2,"A TV?! He's taking a TV?! Jesus... fine, we go on foot, backpacks, forget the car"}},
{"fw_ld5_panic_b062","plan",2,"reg=family|mood=funny",{1,"Mamaw won't leave without her recliner",2,"We can't carry a recliner!",1,"Tell HER that, I'm not telling her that",2,"Wheelbarrow, we put her in the wheelbarrow, she'll scream, but she's coming"}},
{"fw_ld5_panic_b063","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=fear",{1,"Dog won't shut up, he's been at it an hour, they can hear it",2,"So muzzle him",1,"He's my dog, he's trying to tell us something!",2,"So we go where the dog says, but QUIETLY, hold his mouth"}},
{"fw_ld5_panic_b064","plan",2,"reg=civilian,family,worker,rescue|day=0,3|hour=10,23|mood=fear",{1,"Don't-- don't go to the Wilsons', Mr. Wilson's been standing in the yard since morning",2,"Standing how?!",1,"Just standing, facing the goddamn fence, I called his name",2,"...We go around, NOBODY calls anybody's name today"}},
{"fw_ld5_panic_b065","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=fear",{1,"Who the hell's got a gun? I'm not asking, I'm asking WHO",2,"Dave, Dave's got a deer rifle",1,"We go to Dave's, two streets over, close, in a line",2,"And if Dave's not there, if Dave's... we turn around, okay? We don't stand there"}},
{"fw_ld5_panic_b066","plan",2,"reg=civilian,family,worker,rescue|x1=f|day=0,4|hour=10,22|mood=fear",{1,"Phone's dead, I tried my sister in West Point forty times",2,"You're NOT walking to West Point",1,"I'm walking to West Point! I'm walking tonight!",2,"I'm coming, you're not doing it alone, get your shoes"}},
{"fw_ld5_panic_b067","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Mom won't go, she wants to wait for Dad",2,"Dad's at the plant, he's... we don't know where he is",1,"She just SITS there!",2,"We leave a note on the table, big, where we are, and she comes, I'll carry her bag, I'll carry HER if I have to"}},
{"fw_ld5_panic_b068","plan",2,"reg=civilian,family,worker,rescue|x2=m|mood=funny",{1,"Mammoth Cave, we drive to Mammoth Cave, nobody'd ever find us",2,"That's two hours south, and they'd find us",1,"It's a CAVE, it's a hole, it's cold, it's got a gate on it",2,"It's got a gift shop and a parking lot, Pete, no"}},
{"fw_ld5_panic_b069","plan",2,"reg=civilian,family,worker,rescue|day=0,2|mood=fear",{1,"Fill the tub, fill every pot, the water's gonna quit",2,"Why would it quit?!",1,"Because everything else did! Phones, TV, I'm NOT waiting to find out",2,"Tub first, I'm on it, you do the bathroom!"}},
{"fw_ld5_panic_b070","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=fear",{1,"One bag each, that's it, food, shoes, medicine",2,"What-- what about the photos?",1,"NO photos, I'm sorry, we're running!",2,"...Fine, ONE photo, I'm putting it in my shoe",1,"Which one?",2,"The one from the lake, don't ask"}},
{"fw_ld5_panic_b071","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=fear",{1,"Everybody's going north, every car on the damn highway, bumper to bumper",2,"North's where the Army is",1,"North's where EVERYBODY is, that's the problem, I say south",2,"South, away from people, okay, south, I like south"}},
{"fw_ld5_panic_b072","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=calm",{1,"The Guard's coming, they always come, flood of '75 they came in six hours",2,"Two days now",1,"It's a bigger flood! Give it one more day",2,"One, then we go, nobody says I told you so"}},
{"fw_ld5_panic_b073","plan",2,"reg=worker|day=0,3|mood=angry",{1,"It's the plant, I'm telling you, something leaked at the--",2,"Don't start that AGAIN",1,"My cousin works there, he said the whole second shift never came out!",2,"I wanna know less, shut up, pack the truck"}},
{"fw_ld5_panic_b074","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=fear",{1,"Mrs. Pike's eighty-one, ALONE on the corner, we gotta get her",2,"We're barely getting us",1,"She, she baked me cookies every birthday, I'm getting her, come or don't",2,"...Come, we come, you knock, I carry her, she's tiny, she don't weigh nothing"}},
{"fw_ld5_panic_b075","plan",2,"reg=civilian,family,worker,rescue|day=0,2|mood=fear",{1,"The cellar, we go in the cellar, one way in, NOBODY gets down there",2,"We'll be trapped in a hole!",1,"We'll be ALIVE in a hole! Pick one!",2,"Cellar, cellar, okay, flashlight and the Bible, in that order"}},
{"fw_ld5_panic_b076","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=fear",{1,"Highway's a parking lot, we leave the goddamn car, we walk",2,"My mother can't walk that far",1,"Then a wagon, a bike, a shopping cart, I don't know, something with wheels",2,"Shopping cart, yeah, the Kroger's got a hundred, go go go"}},
{"fw_ld5_panic_b077","plan",2,"reg=civilian,family,worker,rescue|day=0,3|mood=angry",{1,"Half to the church, half stay, somebody's still here when your dad comes",2,"We ain't splitting up, not today, not ever",1,"Then we all STAY!",2,"Then we all go! One or the other, but together, damn it"}},
{"fw_ld5_panic_b078","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"We take the cat, we're not leaving the cat",2,"She'll yowl, they'll hear her",1,"She, she goes in my coat and I sing to her, I'm not leaving her",2,"...You'll sing to the cat, God help us, fine, hurry"}},
{"fw_ld5_panic_b079","plan",2,"reg=civilian,family,worker,rescue|day=0,2|mood=fear",{1,"We could try getting higher. I'd want a way back down",2,"Higher doesn't mean safe. Don't let yourself get cornered",1,"Then we check the way up first. I'm not guessing with our lives",2,"All right. Water first, and nobody gets left without a way out"}},
{"fw_ld5_panic_b080","plan",2,"reg=civilian,family,worker,rescue|day=0,2|hour=18,4|mood=fear",{1,"We don't go anywhere in the dark, we wait for sun",2,"It's, it's four hours till sun!",1,"Four hours I can do, four hours of dark out there I can't",2,"...Fine, NOBODY sleeps, nobody makes a sound, we go when it's gray"}},
{"fw_ld5_panic_b081","plan",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"They're saying it's rabies, mad dog rabies in people",2,"Rabies doesn't do that",1,"W-what the hell does?! You tell me what does!",2,"I don't know, I don't know, I just know it's not rabies, so we go"}},
{"fw_ld5_panic_b082","plan",2,"reg=family|day=0,4|mood=fear",{1,"Papaw says go to the farm, forty acres, one gate",2,"Farm's eighteen miles",1,"He's got a shotgun and a smokehouse full of ham, he said so on the phone before it went dead",2,"Then why are we still HERE, load the wagon!"}},
{"fw_ld5_panic_b083","plan",2,"reg=civilian,family,worker,rescue|x2=f|day=0,3|mood=fear",{1,"We gotta decide, we gotta decide NOW",2,"I know, Shelly, I'm trying to think",1,"Think faster! Church or farm or the damn school, pick one!",2,"The church, it's closest, it's got a lock, we go to the church"}},
{"fw_ld5_panic_b084","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Somebody should check the neighbors",2,"Check them how?",1,"Knock on every house, see who's alive, see who needs to come with us",2,"I'm not knocking on every house, I'll knock on four, we go the minute anybody answers wrong"}},
{"fw_ld5_route_b085","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=calm|world=road",{1,"This road runs straight to the Dairy Bar, I walked it Tuesday, it's clear",2,"Clear how? Cars?",1,"Two wrecks and a dead truck, that's all, we can slip past",2,"We go along the shoulder, single file, nobody stops to look at the wrecks"}},
{"fw_ld5_route_b086","plan",2,"reg=civilian,family,worker,rescue|day=1,20|mood=grim|world=road,trees",{1,"If we find a road blocked with cars, do we turn back?",2,"Then we go around",1,"Depends what's beside it. I'm not calling a ditch a route before looking",2,"Agreed. No climbing over cars just because we hate turning around"}},
{"fw_ld5_route_b087","plan",2,"reg=civilian,family,worker,rescue|mood=calm|world=water",{1,"We follow this creek, it comes out right behind the old Tatum place",2,"The creek's low, we can walk the bed",1,"Walk in the water, my granddaddy said hounds can't track you through water",2,"They ain't hounds, but I like it, shoes off, tie 'em round your neck"}},
{"fw_ld5_route_b088","plan",2,"reg=civilian,family,worker,rescue|mood=fear|world=trees",{1,"We cut through the woods here, stay in the trees till we're past the church",2,"Woods are loud, every branch",1,"Roads are louder, nothing to hide behind, we go slow, one foot at a time",2,"...Fine, but you go first"}},
{"fw_ld5_route_b089","plan",2,"reg=civilian,family,worker,rescue|day=3,30|mood=angry|world=inside,building",{1,"We are NOT staying in here another night, I can't breathe",2,"It's the safest place we got",1,"It's a box! A box with no water and a dead fridge!",2,"Then where? Pick a place, ONE place, I'll go"}},
{"fw_ld5_route_b090","plan",2,"reg=civilian,family,worker,rescue|mood=calm|world=vehicle",{1,"If we find an abandoned truck, what would you check first?",2,"Gas?",1,"Keys, fuel, whether it starts. A gauge alone doesn't promise twenty miles",2,"And where we'd leave it if it died. I don't want our whole plan riding on a truck"}},
{"fw_ld5_route_b091","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm|world=cars",{1,"All these cars, one of 'em's gotta have gas",2,"They've been sitting a week, the gas goes bad",1,"It don't go bad in a week, my daddy ran a lawn mower on year-old gas",2,"We check every tank, pull what we can, no talking while we do it"}},
{"fw_ld5_route_b092","plan",2,"reg=civilian,family,worker,rescue|mood=calm|world=rain",{1,"This rain might help with the noise. I still don't like going blind",2,"It's pouring, I can't see ten feet",1,"Then we stop if it gets worse. No running off on your own",2,"Ponchos, trash bags, whatever you got, everybody holds the shoulder in front"}},
{"fw_ld5_route_b093","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=fear|world=fog",{1,"Fog's too thick to move, we'd walk right into something",2,"Or right past something",1,"And I won't know which till it's too late, we wait",2,"We wait quiet, and when it burns off we go, no discussion"}},
{"fw_ld5_route_b094","plan",2,"reg=civilian,family,worker,rescue|day=1,60|mood=angry|world=hot",{1,"It's too hot to move, we wait for evening",2,"Evening's six goddamn hours off!",1,"I know what time evening is, you walk in this and you drop, I'm not carrying you",2,"Fine! Shade, water, nobody does ANYTHING stupid, I'll sit on my hands"}},
{"fw_ld5_route_b095","plan",2,"reg=civilian,family,worker,rescue|day=0,14|mood=fear|world=fire",{1,"Smoke rising over there, a lot of it, something big's burning",2,"Where?",1,"Toward Main, so we don't go toward Main",2,"We go around the north side, keep the damn smoke on our left, we don't stop"}},
{"fw_ld5_route_b096","plan",2,"reg=civilian,family,worker,rescue|mood=calm|world=generator",{1,"You hear that? That's a generator, somebody's got power",2,"Close?",1,"A block, two blocks, I can't tell, but a generator don't run itself",2,"So somebody's there, we go slow, we knock, we don't kick, we say hello first"}},
{"fw_ld5_route_b097","plan",2,"reg=civilian,family,worker,rescue|mood=calm|world=building",{1,"This house is picked clean, the one next door looks untouched",2,"Next door's got a dog sign on the gate",1,"Dog sign, no dog, no barking, ten minutes, I'm going",2,"Wait for me, I ain't being the one left alone in here"}},
{"fw_ld5_route_b098","plan",2,"reg=civilian,family,worker,rescue|day=1,30|hour=17,21|mood=fear",{1,"It's, it's getting dark, we find a place to sleep now, not in an hour, NOW",2,"The school's right there",1,"School's got forty windows and nobody to watch 'em",2,"The church, it's got a bell tower, we sleep up in the tower"}},
{"fw_ld5_route_b099","plan",2,"reg=civilian,family,worker,rescue|day=2,30|hour=21,4|mood=grim",{1,"I'd rather move at night. I feel less exposed, even if that's just in my head",2,"Feeling hidden isn't the same as being hidden",1,"Fine, no promises! We go carefully, and use a light if we need to see",2,"You've thought about this. I'm still going to worry"}},
{"fw_ld5_route_b100","plan",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"If we get split up, we meet at the water tower, everybody hear me?",2,"Water tower, yes",3,"What if the damn water tower's... a problem?",1,"Then the church behind it, and we don't wait more than an hour, I MEAN an hour"}},
{"fw_ld5_route_b101","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=calm",{1,"We leave a note on the church door, where we went, how many of us, what time",2,"Anybody can read it",1,"Anybody we WANT can read it too",2,"...Put the note, but don't say where, just say north, that's enough"}},
{"fw_ld5_route_b102","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=funny",{1,"I used to pass a bike shop on Third. A whole row of ten-speeds",2,"A bike's quieter than a truck",1,"If we found one that worked, it'd beat walking. Wouldn't make it safe, though",2,"You sold me on looking. I ain't ridden since 1979, so don't laugh if I wobble"}},
{"fw_ld5_route_b103","plan",2,"reg=family|x2=m|day=2,30|mood=funny",{1,"The Hendersons got four horses, I could ride to Louisville",2,"You can't ride a horse to Louisville",1,"You ride one, Dan, I lead the others, we'll look like the Pony Express",2,"We'll look like four idiots on horses, but yes, I'm in"}},
{"fw_ld5_route_b104","plan",2,"reg=family|mood=calm",{1,"Mr. Boyd's got a big green tractor, he'd let us borrow it",2,"Tractor does fifteen miles an hour",1,"Tractor goes through anything, a ditch, a gate, I'd rather be slow in a tractor",2,"Fifteen miles an hour with the whole family on the back, fine, load the trailer"}},
{"fw_ld5_route_b105","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"County line's six miles, that's where the Army said they'd stop people",2,"So we don't go to the county line",1,"We go somewhere that isn't a line, Ridge Road, the old logging trail, nobody guards a logging trail",2,"Okay, but if it's blocked we come back, I'm not climbing over somebody's trees"}},
{"fw_ld5_route_b106","plan",2,"reg=civilian,family,worker,rescue|day=1,10|mood=angry",{1,"The goddamn courthouse, somebody's gotta be at the courthouse, a judge, a clerk, SOMEBODY",2,"The whole building's dark, nobody's there",1,"I don't care! I'm walking in there and yelling till somebody answers!",2,"...Okay, we go, but I'm standing outside, I'm counting to a hundred"}},
{"fw_ld5_route_b107","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"Bluegrass Parkway's faster than Dixie, nobody lives on it, nobody stops on it",2,"Nobody's on it because it goes nowhere we want",1,"It goes to Elizabethtown, then east to Bardstown, that's where my aunt is",2,"Bardstown, that's fifty miles, you're serious, we're walking fifty miles",1,"Fifty miles, five days, I'll count my steps if I have to, I'm serious"}},
{"fw_ld5_route_b108","plan",2,"reg=civilian,family,worker,rescue|mood=funny|world=road",{1,"We stand on the road with a thumb out, somebody'll stop",2,"Who's gonna stop?",1,"Somebody with a truck, a kind person, somebody who doesn't know",2,"...If they stop, they're either the nicest person ALIVE or very very dumb, I'm not getting in either truck"}},
{"fw_ld5_route_b109","plan",2,"reg=civilian,family,worker,rescue|day=0,4|mood=fear",{1,"Every payphone we pass, we pick up the receiver",2,"They're dead",1,"Maybe one isn't, maybe one's on a different line, I gotta try",2,"Fine, but quick, I'm not standing next to a payphone for ten minutes"}},
{"fw_ld5_radio_b110","plan",2,"reg=civilian,family,worker,rescue|mood=warm",{1,"My cousin's friend is a DJ at the station in E-town, goes by Big Mike",2,"Big Mike? Like on the radio?",1,"Farm report and the oldies, he'd stay on the air if it was just him and a microphone, I know the type",2,"We find Big Mike, E-town's fifteen miles, I'll go with you"}},
{"fw_ld5_evac_b111","plan",2,"reg=civilian,family,worker,rescue|day=2,14|hour=15,20|mood=fear",{1,"Helicopters come over around seven every night, same direction, same time",2,"What's that way?!",1,"The ridge, there's a flat field, I bet they land, we climb up at dusk, wave a light",2,"And if they're NOT Army? What if they're something else?",1,"We're a light on a hill, we learn something, either way we know"}},
{"fw_ld5_evac_b112","plan",2,"reg=civilian,family,worker,rescue|day=2,20|mood=calm",{1,"We paint HELP on the barn roof, forty feet tall, white paint, you'd see it from a plane",2,"Nobody's flying planes",1,"Somebody is, I heard one Tuesday, high up, going north",2,"...Fine, but I'm not climbing, I'll hold the ladder, you hold the paint"}},
{"fw_ld5_route_b113","plan",2,"reg=civilian,family,worker,rescue|day=1,30|hour=5,12|mood=calm",{1,"Next town's ten miles, leave now, we make it by dark",2,"Ten miles with the packs?",1,"Four hours if we don't stop, five if we do, I say we don't",2,"I say we stop once for water, and I'm not taking a vote"}},
{"fw_ld5_route_b114","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"Dixie's flat as a pancake, twenty miles on bikes, we'd be there by noon",2,"I can't ride a bike",1,"You can't ride a bike? You're thirty-eight!",2,"Never learned, not learning now, put me on the back"}},
{"fw_ld5_radio_b115","plan",2,"reg=worker|day=1,14|mood=calm",{1,"There's a trucker at the weigh station, I seen his rig, he'd know the roads",2,"Truckers know every back way, they'd tell us where the Army is",1,"They'd tell us for a cigarette, I got half a pack",2,"Half a pack for the whole state of Kentucky, that's a bargain"}},
{"fw_ld5_evac_b116","plan",2,"reg=civilian,family,worker,rescue|day=2,14|mood=fear",{1,"Somebody said the Army's got a camp near Bardstown",2,"Bardstown's forty miles",1,"East, the bourbon warehouses, big, empty, good roofs",2,"Forty miles of walking, I need a plan for water, I need shoes"}},
{"fw_ld5_radio_b117","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=calm",{1,"Ask the pastor, he knows the ham guy, he's on the church radio every Sunday",2,"Church radio's mostly hymns",1,"It's got a long wire up the steeple, picks up anything",2,"We go ask, and if he's not there we climb the steeple ourselves"}},
{"fw_ld5_route_b118","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=angry",{1,"Nine days we been here, I say we stay",2,"Nine days, I say we go",1,"You-- you always wanna go!",2,"Because there's NOTHING here!",1,"There's nothing everywhere!",2,"...We flip a coin, heads we go, tails we stay, I'll try to lose nice"}},
{"fw_ld5_route_b119","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Don't look at the cars, just walk",2,"I wasn't looking",1,"You-- you were looking, everyone does, don't",2,"...I'll look at my shoes, they're in better shape than the cars"}},
{"fw_ld5_water_c001","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=angry|world=water",{1,"Drink it, then, go ahead, drink the creek, see how you like it",2,"I hoped moving water would be all right. I don't actually know",1,"Hope isn't a water test, Hank! We can't tell what's upstream just standing here!",2,"...Then we don't drink it as it is. Fine. I hate that you're right"}},
{"fw_ld5_water_c002","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"A water heater might be worth checking",2,"For water?",1,"Maybe. We check what's there first, not call it clean before we've even found one"}},
{"fw_ld5_water_c003","plan",2,"reg=civilian,family,worker,rescue|mood=grim",{1,"Two gallons, and the baby's got one of 'em",2,"So one gallon between six people",1,"I counted twice! I'd count again but the number's not gonna change",2,"The creek or the pool or the neighbor's well, pick one, we're out by tomorrow"}},
{"fw_ld5_water_c004","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=calm",{1,"I heard somebody say you could use bleach for drinking water",1,"But I'm not turning something I half remember into instructions. I'm not making us sick on a guess",2,"Good. I'd rather you say you don't know",1,"Let's look for water we can actually use, not a shortcut somebody swore by"}},
{"fw_ld5_water_c005","plan",3,"reg=civilian,family,worker,rescue|mood=calm",{1,"My uncle's got a well at the old place, hand pump, four miles",2,"Four miles there, four back, with buckets",3,"Wagon, wheelbarrow, every bucket, one big trip",1,"One trip, and we fill every jug we got",2,"...Fine, but I'm not pulling the goddamn wagon the whole way, we trade off"}},
{"fw_ld5_water_c006","plan",2,"reg=civilian,family,worker,rescue|day=1,30|mood=calm|world=rain",{1,"Rain's coming down, put out everything, every bucket, pot, the kids' pool",2,"What about the roof gutters?",1,"Gutter's rusty, but a bucket under the downspout is fine, boil it later",2,"Everybody grab something, MOVE, it won't last long"}},
{"fw_ld5_water_c007","plan",2,"reg=worker|day=5,200|mood=funny",{1,"Water tower's got a hundred thousand gallons up top, there's a hatch, I seen the guys go up",2,"You want to climb a water tower",1,"I want to open a valve at the bottom and watch it come out",2,"There's no valve, Dale, it feeds the whole town, it's just sitting up there",1,"...I'm still looking at it tomorrow, I'm not letting it go"}},
{"fw_ld5_water_c008","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"The neighbor's pool is green but it's a pool, there's ten thousand gallons in it, we can just--",2,"Don't drink it",1,"For washing, the toilets, the kids, for everything but drinking, we save the good water for drinking",2,"Okay",2,"I'm in, who's got a bucket"}},
{"fw_ld5_water_c009","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=sad",{1,"We drank the creek water yesterday, and now Dale's throwing up",2,"I told you to boil it",1,"I KNOW you told me! I'm not saying you didn't! I'm saying what do we do now!",2,"Water, clean, a little at a time, and I'll boil every drop from here on, I'll set an alarm"}},
{"fw_ld5_water_c010","plan",2,"reg=civilian,family,worker,rescue|mood=calm",{1,"Who the hell's got a canteen? One canteen between all of us",2,"There's the thermos, the jugs from the basement",1,"Jugs, yeah, every jug we find, we fill 'em all, we carry 'em on a pole",2,"A pole! Like in the cartoons, fine, I'll find a pole"}},
{"fw_ld5_water_c011","plan",2,"reg=civilian,family,worker,rescue|day=1,14|mood=fear",{1,"Is there water at the church?",2,"Pastor's got a well",1,"Then we go there"}},
{"fw_ld5_meds_c012","plan",2,"reg=civilian,family,worker,rescue|day=2,30|mood=grim",{1,"Out of bandages, we're tearing up the bed sheets",2,"Boil 'em first",1,"I know to boil 'em, I'm not a child, what I need is the real kind, the white kind in the little paper",2,"So it's the drugstore or the clinic, I don't care which, I'll go to either one, shit"}},
{"fw_ld5_meds_c013","plan",2,"reg=civilian,family,worker,rescue|mood=funny",{1,"If we ran out of proper wound supplies, would you really reach for whiskey?",2,"I've heard people suggest it",1,"I wouldn't trust a bottle to do a medic's job",2,"And giving the patient a swig wouldn't make it proper treatment either"}},
{"fw_ld5_meds_c014","plan",2,"reg=civilian,family,worker,rescue|day=0,10|mood=fear",{1,"She's burning up, I can feel it through the blanket",2,"How-- how the hell high?",1,"I don't have a thermometer! I don't have anything!",2,"There's a drugstore two blocks over, we get a thermometer, aspirin, if it doesn't go down we take her to the doc"}},
{"fw_ld5_meds_c015","plan",2,"reg=civilian,family,worker,rescue|mood=sad",{1,"Tom's ankle's the size of a melon, he can't put weight on it",2,"So we carry him",1,"For how far? We can't carry him fifty miles",2,"We find crutches at the pharmacy, or a wheelchair, anything with wheels"}},
{"fw_ld5_meds_c016","plan",2,"reg=family|day=2,30|mood=calm",{1,"Papaw's out of his blood pressure pills, he doesn't say it but I counted",2,"How many left?",1,"Zero, he's been skipping every other day, he thinks I don't notice",2,"The drugstore, we bring the empty bottle, the label's got the name, the dose"}},
{"fw_ld5_meds_c017","plan",2,"reg=civilian,family,worker,rescue|day=5,60|mood=warm",{1,"She's due in September, she's got no doctor, she's been so brave about it",2,"There's a midwife out past the church, Mrs. Doyle, delivered half the babies in this county",1,"Is she still alive? Is she still THERE?",2,"We go see, tomorrow, first thing, that's all I got"}},
}
